import os
import hmac
import hashlib
import json
import ipaddress
from urllib.parse import urlparse
from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET')
if not WEBHOOK_SECRET:
    raise RuntimeError(
        "WEBHOOK_SECRET environment variable must be set; refusing to start "
        "with an insecure default secret."
    )
FEATURE_FLAGS_URL = os.environ.get('FLAGS_SERVICE', 'http://flags-internal:8080')

# Feature flag cache
_flag_cache = {}

def get_feature_flag(flag_name, default=False):
    """Fetch feature flag from internal service with caching."""
    if flag_name in _flag_cache:
        return _flag_cache[flag_name]
    try:
        resp = requests.get(f"{FEATURE_FLAGS_URL}/api/flags/{flag_name}", timeout=2)
        if resp.status_code == 200:
            value = resp.json().get('enabled', default)
            _flag_cache[flag_name] = value
            return value
    except requests.RequestException:
        pass
    return default


def verify_webhook_signature(payload_body, signature):
    """Verify GitHub-style webhook signature."""
    if not signature:
        return False
    expected = 'sha256=' + hmac.new(
        WEBHOOK_SECRET.encode(),
        payload_body,
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)


def is_internal_network(url):
    """Check if URL resolves to internal/private network."""
    try:
        parsed = urlparse(url)
        hostname = parsed.hostname
        if not hostname:
            return True
        # Block obvious internal patterns
        if hostname in ('localhost', '127.0.0.1', '0.0.0.0', '::1'):
            return True
        if hostname.endswith('.internal') or hostname.endswith('.local'):
            return True
        # Check for private IP ranges
        try:
            ip = ipaddress.ip_address(hostname)
            return ip.is_private or ip.is_loopback or ip.is_link_local
        except ValueError:
            pass
        return False
    except Exception:
        return True


def validate_artifact_url(url):
    """Validate that artifact URL is safe to fetch."""
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return False, "Invalid scheme"
    if is_internal_network(url):
        return False, "Internal network access denied"
    return True, None


ALLOWED_MIRROR_HOSTS = frozenset([
    'mirror-proxy.internal',
    'cache-proxy.internal',
])


def resolve_artifact_mirror(artifact_url, build_config):
    """Resolve artifact URL through configured mirrors.

    When mirror_mode is enabled via feature flag, artifacts are fetched
    through the configured mirror proxy for caching purposes.
    """
    use_mirror = get_feature_flag('artifact_mirror_mode', default=False)

    if use_mirror and 'mirror_proxy' in build_config:
        mirror_base = build_config['mirror_proxy']
        # Validate mirror is in our allowed list
        parsed_mirror = urlparse(mirror_base)
        if parsed_mirror.hostname not in ALLOWED_MIRROR_HOSTS:
            return artifact_url
        if parsed_mirror.scheme not in ('http', 'https'):
            return artifact_url
        # Mirror proxy fetches on our behalf - construct proxy URL
        proxy_url = f"{mirror_base}/fetch?target={artifact_url}"
        return proxy_url

    return artifact_url


def fetch_build_artifact(url, build_config):
    """Fetch a build artifact, optionally through mirror."""
    resolved_url = resolve_artifact_mirror(url, build_config)

    # Always validate the final URL
    valid, err = validate_artifact_url(resolved_url)
    if not valid:
        # If mirror URL fails validation, try direct
        if resolved_url != url:
            valid, err = validate_artifact_url(url)
            if not valid:
                return None, err
            resolved_url = url
        else:
            return None, err

    try:
        resp = requests.get(resolved_url, timeout=30, allow_redirects=False)
        return resp.content, None
    except requests.RequestException as e:
        return None, str(e)


@app.route('/api/pipeline/trigger', methods=['POST'])
def trigger_pipeline():
    """Trigger a CI/CD pipeline build."""
    sig = request.headers.get('X-Hub-Signature-256')
    if not verify_webhook_signature(request.data, sig):
        return jsonify({'error': 'Invalid signature'}), 401

    payload = request.get_json()
    if not payload:
        return jsonify({'error': 'Invalid payload'}), 400

    build_config = payload.get('build_config', {})
    artifacts = payload.get('artifacts', [])

    results = []
    for artifact in artifacts:
        artifact_url = artifact.get('url', '')

        # First validate the user-supplied URL
        valid, err = validate_artifact_url(artifact_url)
        if not valid:
            results.append({'url': artifact_url, 'error': err})
            continue

        # Fetch through pipeline (may use mirror)
        content, err = fetch_build_artifact(artifact_url, build_config)
        if err:
            results.append({'url': artifact_url, 'error': err})
        else:
            results.append({'url': artifact_url, 'size': len(content)})

    return jsonify({'results': results})


@app.route('/health')
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
